    example: "- Ten thousand users hash to a 10.0% canary share, and the same user always lands in the same variant\n- A flag with a 5% rollout, one allow-listed user and one blocked user resolves correctly for all three cases, and the kill switch overrides all of them\n- A 10% error rate on 1,000 canary requests is statistically significant and triggers an immediate rollback to 0%\n- Two errors in a thousand is not significant, so the controller holds rather than rolling back a healthy release\n- A p95 of 400ms against a 120ms baseline rolls back even though the error rate is clean",
    code: "// Sticky bucketing: hash a stable identity, salted per experiment.\nexport function bucket(key, salt) {\n  const digest = createHash('sha256').update(salt + ':' + key).digest();\n  return digest.readUInt32BE(0) % 100;   // Math.random() here would reshuffle per request\n}\n\n// Flag precedence: kill switch, block, allow, percentage — in that order.\nif (!flag.enabled) return { on: false, reason: 'flag disabled' };\nif (flag.blockUsers?.includes(userId)) return { on: false, reason: 'user blocked' };\nif (flag.allowUsers?.includes(userId)) return { on: true, reason: 'user allow-listed' };\nreturn { on: bucket(userId, flag.key) < flag.percentage, reason: 'rollout bucket' };\n\n// The controller: hold without samples, roll back to ZERO on a real regression.\nif (metrics.canary.total < minSamples) return { action: 'hold', weights: { stable: 100 - current, canary: current } };\nif (compareErrorRates(metrics.baseline, metrics.canary).significant) {\n  return { action: 'rollback', weights: { stable: 100, canary: 0 } };\n}",
